$('projectFile').onchange=async e=>{if(converting)return toast('请等待转换完成');try{const d=JSON.parse(await e.target.files[0].text());if(confirm('导入会先备份当前作品，是否继续？')&&archiveCurrent('导入前'))restore(d)}catch(err){toast(err.message)}};$('paletteFile').onchange=async e=>{if(converting)return toast('请等待转换完成');try{let p=JSON.parse(await e.target.files[0].text());if(!validPalette(p))throw Error('色卡格式不正确，或存在重复色号');let old=palette;if(!confirm('将按新色卡匹配当前作品颜色，是否继续？'))return;if(!archiveCurrent('导入色卡前'))return;completedRows=[];palette=p;cells=cells.map(v=>v<0?-1:nearest(rgb(old[v].hex)));paletteName=e.target.files[0].name.replace(/\.json$/,'')+' · 自定义色卡';selected=0;undo=[];redo=[];changed();toast('色卡已导入，请确认色号准确性')}catch(err){toast(err.message)}};
function counts(){const n=Array(palette.length).fill(0);cells.forEach(v=>{if(v>=0)n[v]++});return palette.map((p,i)=>({...p,count:n[i]})).filter(p=>p.count)}const csvQuote=s=>'"'+String(s).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';$('materials').onclick=()=>{let rows=[['作品',$('title').value],['色卡',paletteName],['网格',`${w}x${h}`],['间距mm',$('pitch').value],['色号','参考颜色','颗数'],...counts().map(p=>[p.id,p.hex,p.count])];download(new Blob(['\ufeff'+rows.map(r=>r.map(csvQuote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),basename()+'-材料清单.csv')};
function chart(x0=0,y0=0,cw=w,ch=h){let unit=Math.max(cw,ch)>160?20:32,margin=50,legend=regionCounts(x0,y0,cw,ch),cols=4,canvas=document.createElement('canvas');canvas.width=Math.max(850,cw*unit+margin*2);canvas.height=ch*unit+170+Math.ceil(legend.length/cols)*34;let c=canvas.getContext('2d');c.fillStyle='white';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#293f35';c.font='bold 22px sans-serif';c.fillText($('title').value||'我的拼豆',margin,35);c.font='13px sans-serif';c.fillText(`${w}×${h} 颗 · ${$('pitch').value}mm 间距 · ${paletteName}`,margin,60);for(let y=0;y<ch;y++)for(let x=0;x<cw;x++){let v=cells[(y+y0)*w+x+x0],px=margin+x*unit,py=100+y*unit;if(v>=0){let p=palette[v];c.fillStyle=p.hex;c.fillRect(px,py,unit,unit);let [r,g,b]=rgb(p.hex);c.fillStyle=r*.299+g*.587+b*.114>145?'#222':'#fff';c.font=(unit<32?'7px':'9px')+' sans-serif';c.textAlign='center';c.fillText(p.id,px+unit/2,py+unit/2+3)}c.strokeStyle='#999';c.lineWidth=.5;c.strokeRect(px,py,unit,unit)}c.textAlign='center';c.fillStyle='#555';c.font='10px sans-serif';for(let x=0;x<cw;x++)c.fillText(x+x0+1,margin+x*unit+unit/2,93);c.textAlign='right';for(let y=0;y<ch;y++)c.fillText(y+y0+1,margin-8,100+unit*.6+y*unit);c.textAlign='left';legend.forEach((p,i)=>{let x=margin+i%cols*((canvas.width-margin*2)/cols),y=ch*unit+135+Math.floor(i/cols)*34;c.fillStyle=p.hex;c.fillRect(x,y-12,16,16);c.strokeStyle='#aaa';c.strokeRect(x,y-12,16,16);c.fillStyle='#333';c.font='12px sans-serif';c.fillText(`${p.id}  ${p.count}颗（本图）`,x+23,y)});return canvas}
$('export').onclick=()=>$('exportDialog').showModal();$('closeDialog').onclick=()=>$('exportDialog').close();$('png').onclick=()=>{try{chart().toBlob(b=>b?download(b,basename()+'-制作图.png'):toast('导出失败，请使用分页打印'))}catch{toast('图纸过大，请使用分页打印')}};$('shot').onclick=()=>{renderer.render(scene,camera);renderer.domElement.toBlob(b=>{if(b)download(b,basename()+'-3D.png')})};$('print').onclick=()=>{let size=+$('boardSize').value;if(!Number.isInteger(size)||size<8||size>64)return toast('分区边长请输入 8–64 的整数');let win=window.open('','_blank');if(!win)return toast('请允许弹窗以打开打印页面');win.document.write('<!doctype html><html lang="zh-CN"><head><title>拼豆分页图纸</title><style>@page{size:A4;margin:10mm}body{margin:0}img{width:100%;max-height:255mm;object-fit:contain;display:block}section{break-after:page}section:last-of-type{break-after:auto}@media print{button{display:none}}</style></head><body></body></html>');for(let y=0;y<h;y+=size)for(let x=0;x<w;x+=size){let img=win.document.createElement('img');img.src=chart(x,y,Math.min(size,w-x),Math.min(size,h-y)).toDataURL();let section=win.document.createElement('section'),heading=win.document.createElement('p');heading.textContent=`分区 ${Math.floor(y/size)+1}-${Math.floor(x/size)+1} · 行 ${y+1}–${Math.min(y+size,h)} · 列 ${x+1}–${Math.min(x+size,w)}`;section.append(heading,img);win.document.body.append(section)}let b=win.document.createElement('button');b.textContent='打印 / 另存为 PDF';b.onclick=()=>win.print();win.document.body.prepend(b);win.document.close()};
function libraryItems(){try{const a=JSON.parse(localStorage.getItem('bead-studio-library-v1')||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function archiveCurrent(reason='作品副本'){if(!cells.length)return true;try{let items=libraryItems(),d=data(),signature=JSON.stringify(d);if(reason!=='作品副本'&&items.some(x=>JSON.stringify(x.work)===signature))return true;items.unshift({id:crypto.randomUUID(),reason,time:new Date().toISOString(),work:d});localStorage.setItem('bead-studio-library-v1',JSON.stringify(items.slice(0,12)));return true}catch{toast('作品库空间不足，请先导出 JSON；当前图案未被替换');return false}}
$('saveCopy').onclick=()=>{if(archiveCurrent())toast('副本已加入本地作品库')};
$('library').onclick=()=>{const list=$('libraryList');list.replaceChildren();let items=libraryItems();if(!items.length)list.textContent='还没有副本。点击“存为副本”，保存当前作品。';items.forEach(item=>{let card=document.createElement('article'),title=document.createElement('strong'),meta=document.createElement('p'),open=document.createElement('button'),backup=document.createElement('button');title.textContent=item.work.title||'未命名作品';meta.textContent=`${item.reason} · ${item.work.w} × ${item.work.h} · ${new Date(item.time).toLocaleString('zh-CN')}`;open.textContent='打开此版本';open.disabled=converting;open.onclick=()=>{if(converting)return;if(!archiveCurrent('打开其他作品前'))return;try{restore(item.work);$('libraryDialog').close();toast('已恢复图案；重新转换需要再次上传原图')}catch(e){toast(e.message)}};backup.textContent='导出 JSON';backup.onclick=()=>download(new Blob([JSON.stringify(item.work)],{type:'application/json'}),'拼豆作品备份.json');card.append(title,meta,open,backup);list.append(card)});$('libraryDialog').showModal()};$('closeLibrary').onclick=()=>$('libraryDialog').close();
function restrictedIndices(){return paletteIndices($('allowedColors').value,palette)}
