$('cropMode').addEventListener('change',estimate);$('mobileImage').onchange=e=>loadImage(e.target.files[0]);document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{$('size').value=b.dataset.goal;$('size').oninput();$('colors').value=16;syncColorLimit();estimate();toast('已设为16色上限；点击重新生成后应用')});
$('paletteSearch').oninput=()=>selectColor(selected);$('usedOnly').onchange=()=>selectColor(selected);
function syncFollow(center=false){followRow=Math.max(1,Math.min(h,followRow));$('followRow').max=h;$('followRow').value=followRow;const done=new Set(completedRows);let total=0,finished=0;cells.forEach((v,i)=>{if(v>=0){total++;if(done.has(Math.floor(i/w)))finished++}});$('followProgress').textContent=`已完成 ${completedRows.length}/${h} 行 · ${finished.toLocaleString()}/${total.toLocaleString()} 颗 · ${total?Math.round(finished/total*100):0}%`;$('completeRow').textContent=done.has(followRow-1)?'取消本行完成':'标记本行完成';$('prevRow').disabled=followRow<=1;$('nextRow').disabled=followRow>=h;if(mode==='follow'){if(center){const scale=Math.min(($('stage').clientWidth-32)/w,($('stage').clientHeight-70)/h)*zoom;panY=(h/2-followRow+.5)*scale}$('stageHelp').textContent=`第 ${followRow} 行 · 拖动平移，轻点定位`;render2d()}}
$('viewFollow').onclick=()=>{setMode('follow');syncFollow()};$('prevRow').onclick=()=>{followRow--;syncFollow(true)};$('nextRow').onclick=()=>{followRow++;syncFollow(true)};$('followRow').oninput=()=>{followRow=Number.isFinite(+$('followRow').value)?Math.round(+$('followRow').value):1;syncFollow(true)};$('highlightColor').onchange=render2d;$('completeRow').onclick=()=>{const i=followRow-1;completedRows=completedRows.includes(i)?completedRows.filter(v=>v!==i):[...completedRows,i];syncFollow();save(true)};
let mergeTarget=-1,mergeFrom=-1;
$('mergeColor').onclick=()=>{if(converting)return toast('请等待转换完成');const use=counts();mergeFrom=selected;const candidates=use.filter(p=>p.id!==palette[selected].id);if(!cells.includes(selected)||!candidates.length)return toast('请选择已用颜色，且作品至少需要两种颜色');const a=lab(rgb(palette[selected].hex)),distance=p=>lab(rgb(p.hex)).reduce((sum,v,i)=>sum+(v-a[i])**2,0);candidates.sort((a,b)=>distance(a)-distance(b));mergeTarget=palette.findIndex(p=>p.id===candidates[0].id);$('mergeSummary').textContent=`把 ${palette[selected].id}（${cells.filter(v=>v===selected).length} 颗）替换成 ${palette[mergeTarget].id}，用色数将减少一种。请先确认颜色差异。`;$('mergeSwatches').replaceChildren(...[selected,mergeTarget].map(i=>{const el=document.createElement('span');el.style.background=palette[i].hex;el.title=palette[i].id;el.setAttribute('aria-label',palette[i].id);return el}));$('mergeDialog').showModal()};$('cancelMerge').onclick=()=>$('mergeDialog').close();$('confirmMerge').onclick=()=>{if(!archiveCurrent('合并颜色前'))return;history();cells=cells.map(v=>v===mergeFrom?mergeTarget:v);selected=mergeTarget;changed();$('mergeDialog').close();toast('颜色已合并，可以撤销')};
