function clearTemporaryPan(){spaceDown=false;editor.classList.remove('temporary-pan')}
document.addEventListener('keydown',e=>{const target=e.target,editable=!!target.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'),dialog=!!document.querySelector('dialog[open]');const action=shortcutAction(e,{mode,editable,dialog,button:!!target.closest?.('button,a')});if(!action)return;if(action==='holdPan'){e.preventDefault();spaceDown=true;editor.classList.add('temporary-pan');return}if(drawing||panStart||touchPoints.size)return;if((action==='undo'||action==='redo')&&mode==='follow')return;e.preventDefault();if(action==='help'){$('shortcutsDialog').showModal();return}if(['3d','2d','follow'].includes(action)){setMode(action);if(action==='follow')syncFollow();return}if(action.startsWith('tool:')){document.querySelector(`[data-tool="${action.slice(5)}"]`).click();return}if(action.startsWith('pan:')){const direction=action.slice(4),step=e.shiftKey?160:40;panX+=direction==='left'?-step:direction==='right'?step:0;panY+=direction==='up'?-step:direction==='down'?step:0;render2d();return}if(action==='fit'){if(mode==='3d')resetView();else fit2d();return}if(action==='zoomIn'||action==='zoomOut'){zoomTo(zoom*(action==='zoomIn'?1.25:.8));return}if(['completeRow','save'].includes(action)&&e.repeat)return;$(action).click()});
document.addEventListener('keyup',e=>{if(e.key===' ')clearTemporaryPan()});window.addEventListener('blur',()=>{clearTemporaryPan();panStart=null});document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTemporaryPan()});
$('shortcutsOpen').onclick=()=>{clearTemporaryPan();$('shortcutsDialog').showModal()};$('shortcutsClose').onclick=()=>$('shortcutsDialog').close();$('shortcutsDone').onclick=()=>$('shortcutsDialog').close();
const shortcutLabels={paint:'B',erase:'E',fill:'G',pick:'I',pan:'H'};document.querySelectorAll('[data-tool]').forEach(b=>{const key=shortcutLabels[b.dataset.tool];b.title=`${b.textContent.trim()}（${key}）`;b.setAttribute('aria-keyshortcuts',key)});[['view3d','1'],['view2d','2'],['viewFollow','3'],['zoomIn','+'],['zoomOut','-'],['zoomFit','0'],['prevRow','['],['nextRow',']'],['centerRow','C']].forEach(([id,key])=>{$(id).title=`${$(id).textContent.trim()}（${key}）`;$(id).setAttribute('aria-keyshortcuts',key)});

